parameters.content:
{
  "id": "7858627c-b79d-4e09-a006-915b5855926f",
  "version": "1.8",
  "name": "POReview",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "16e70191-a6d6-49ce-887e-d404b0e8da18",
        "isDefaultEntryPoint": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the trigger.",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "hitlReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "PO Review"
      },
      "inputs": {
        "title": "Purchase Order Review",
        "priority": "Medium",
        "schema": {
          "schemaId": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
          "fields": [
            {
              "id": "poNumber",
              "label": "PO Number",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.poNumber"
            },
            {
              "id": "vendorName",
              "label": "Vendor Name",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.vendorName"
            },
            {
              "id": "totalAmount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.start.output.totalAmount"
            },
            {
              "id": "notes",
              "label": "Notes",
              "type": "text",
              "direction": "output",
              "variable": "vars.reviewNotes"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "End"
            }
          ]
        },
        "recipient": {
          "channels": [
            "Email",
            "ActionCenter"
          ],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "notes": {
              "type": "string"
            },
            "Action": {
              "type": "string",
              "enum": [
                "Approve",
                "Reject"
              ],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": [
            "Approve",
            "Reject"
          ],
          "default": "Approve"
        }
      }
    },
    {
      "id": "decisionApproved",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.hitlReview.status === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "logApproval",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Approval"
      },
      "inputs": {
        "script": "return {\n  message: \"Purchase order approved\",\n  poNumber: $vars.start.output.poNumber,\n  vendorName: $vars.start.output.vendorName,\n  totalAmount: $vars.start.output.totalAmount,\n  notes: $vars.hitlReview.output.notes\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=result.Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endApproved",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End — Approved"
      },
      "inputs": {},
      "outputs": {}
    },
    {
      "id": "endRejected",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End — Rejected"
      },
      "inputs": {},
      "outputs": {}
    }
  ],
  "edges": [
    {
      "id": "edge-start-hitl",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "hitlReview",
      "targetPort": "input"
    },
    {
      "id": "edge-hitl-decision",
      "sourceNodeId": "hitlReview",
      "sourcePort": "completed",
      "targetNodeId": "decisionApproved",
      "targetPort": "input"
    },
    {
      "id": "edge-decision-log",
      "sourceNodeId": "decisionApproved",
      "sourcePort": "true",
      "targetNodeId": "logApproval",
      "targetPort": "input"
    },
    {
      "id": "edge-decision-rejected",
      "sourceNodeId": "decisionApproved",
      "sourcePort": "false",
      "targetNodeId": "endRejected",
      "targetPort": "input"
    },
    {
      "id": "edge-log-end-approved",
      "sourceNodeId": "logApproval",
      "sourcePort": "success",
      "targetNodeId": "endApproved",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start workflow manually",
      "tags": [
        "trigger",
        "start",
        "manual"
      ],
      "sortOrder": 40,
      "display": {
        "label": "Manual trigger",
        "icon": "play",
        "shape": "circle"
      },
      "handleConfiguration": [
        {
          "position": "right",
          "handles": [
            {
